```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    vector<int> d(n - 1);
    for (int i = 0; i < n - 1; i++)
        d[i] = T[i + 1] - T[i];

    int maxDl = 1, maxStart = 0;
    int curDl = 1, curStart = 0;

    for (int i = 1; i < (int)d.size(); i++) {
        if (d[i] > d[i - 1]) {
            curDl++;
        } else {
            if (curDl > maxDl) {
                maxDl = curDl;
                maxStart = curStart;
            }
            curDl = 1;
            curStart = i;
        }
    }
    if (curDl > maxDl) {
        maxDl = curDl;
        maxStart = curStart;
    }

    cout << "Najdluzszy ciag rosnacych roznic: dlugosc " << maxDl << endl;
    cout << "Roznice:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << d[i];
    cout << endl;
    cout << "Elementy ciagu:";
    for (int i = maxStart; i <= maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Obliczamy tablice roznic, potem stosujemy wzorzec current/max do szukania najdluzszego scisle rosnacego podciagu w tablicy roznic. Fragment roznic d[a..b] odpowiada elementom T[a..b+1].

